- // previous placeholder autoscaler
+ // queue-driven autoscaler samples queue depth and tail-latency slippage
+ func evaluateShard(shard SampleWindow) Decision {
+     slippage := shard.P99 / shard.BaselineP99
+     if shard.QueueGrowthRate > cfg.QueueGrowthThreshold || slippage > cfg.SlippageThreshold {
+         return ScaleUp
+     }
+     return MaybeScaleDown
+ }

